entries.command:
cd "E:\github_maochenyu_me\BroadcastChannel" && [Console]::OutputEncoding=[Text.Encoding]::UTF8
agent-browser --session ini close 2>&1 | Select-Object -First 1
Write-Output "=== 方案A: --proxy-bypass 放行内网 ==="
$job = Start-Job {
  agent-browser --session fix1 --proxy-bypass "localhost,127.0.0.1,192.168.*,10.*,172.16.*,*.local" open "http://192.168.0.220:8765/" 2>&1 | Select-Object -First 4
}
$null = Wait-Job $job -Timeout 55
if($job.State -eq "Completed"){ Receive-Job $job } else { Write-Output "[启动中]"; Stop-Job $job }

