entries.command:
cd "E:\github_maochenyu_me\BroadcastChannel" && [Console]::OutputEncoding=[Text.Encoding]::UTF8
Write-Output "=== 清理: 关闭浏览器 + 停演示服务器 ==="
agent-browser close --all 2>&1 | Select-Object -First 2
Get-CimInstance Win32_Process -Filter "Name='python.exe'" -EA SilentlyContinue | Where-Object { $_.CommandLine -like "*8765*" } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -EA SilentlyContinue; Write-Output "已停 PID $($_.ProcessId)" }
Start-Sleep -Seconds 1
Get-NetTCPConnection -State Listen -LocalPort 8765 -EA SilentlyContinue | Measure-Object | ForEach-Object { Write-Output "8765 监听数: $($_.Count)" }

